function construct_direct_gsn_basis(lambda, m, nu, omega)
    return construct_direct_gsn_basis_yc_s0(lambda, m, nu, omega)
end

function eval_direct_gsn_basis!(out::Vector{ComplexF64}, coeffs::Vector{ComplexF64}, x0)
    x0 = ComplexF64(x0)
    return eval_direct_gsn_basis_yc_s0!(out, coeffs, 1.0 - x0)
end

function eval_direct_gsn_basis_variable!(out::Vector{ComplexF64}, coeffs::Vector{ComplexF64}, value)
